import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class KeywordMatcher {
    public static void main(String[] args) {
        // 원본 데이터와 대조할 키워드들
        String[] originalData = {"apple is a fruit", "banana is a fruit", "cherry is a fruit", "date is a fruit"};
        String[] keywords = {"apple", "banana", "date"};

        // 대조한 결과를 저장할 Map
        Map<String, List<String>> keywordMap = new HashMap<>();

        // 원본 데이터에서 각 문자열을 꺼내어 대조
        for (String data : originalData) {
            for (String keyword : keywords) {
                if (data.contains(keyword)) {
                    // 대조한 키워드를 포함하는 경우, Map에 추가
                    keywordMap.computeIfAbsent(keyword, k -> new ArrayList<>()).add(data);
                }
            }
        }

        // 대조 결과 출력
        for (Map.Entry<String, List<String>> entry : keywordMap.entrySet()) {
            String keyword = entry.getKey();
            List<String> matchingDataList = entry.getValue();

            System.out.println("Keyword: " + keyword);
            System.out.println("Matching Data: " + matchingDataList);
        }
    }
}

